  useEffect(() => {
    let disposed = false;
    let unlistenUndo: (() => void) | undefined;
    let unlistenRedo: (() => void) | undefined;
    const cleanup = () => {
      unlistenUndo?.();
      unlistenRedo?.();
      unlistenUndo = undefined;
      unlistenRedo = undefined;
    };
