  if (source === null) return null;
  switch (source.kind) {
    case 'loop-placeholder':
      return null;
    case 'real':
    case 'generated':
      return source;
    default: {
      const exhaustive: never = source;
      throw new Error(`Unhandled Roto physical render-source kind: ${JSON.stringify(exhaustive)}`);
    }
  }
